/* Publish parked parent callee-saved into fork_saved_* for FORK_PARENT/COOP.
 * yield_to_child parks parent rbx… here and loads child regs into fork_saved_*
 * for the switch; without republishing, child exit would restore child rbp/rbx
 * into ash and trash the next pipeline (garbage RIP / tiny RSP). */
static void bfree_coop_publish_parent_callee_saved(void)
{
    g_bfree_fork_saved_rbx = g_coop_parent_rbx;
    g_bfree_fork_saved_rbp = g_coop_parent_rbp;
    g_bfree_fork_saved_r12 = g_coop_parent_r12;
    g_bfree_fork_saved_r13 = g_coop_parent_r13;
    g_bfree_fork_saved_r14 = g_coop_parent_r14;
    g_bfree_fork_saved_r15 = g_coop_parent_r15;
    g_bfree_fork_saved_rdx = g_coop_parent_rdx;
}

